 async function request(action,payload={},endpoint=ENDPOINT){const current=epoch;let response;try{response=await fetch(endpoint,{method:'POST',credentials:'omit',signal:AbortSignal.timeout(20000),headers:{'Content-Type':'application/json',...(token&&!(endpoint===ACCESS_ENDPOINT&&action.startsWith('access_'))?{Authorization:'Bearer '+token}:{})},body:JSON.stringify({action,payload})});}catch{throw new Error('The service could not confirm this action. Your draft is still here. Refresh to check whether it saved before submitting again.');}if(current!==epoch)throw new Error('Your session ended. Sign in again to continue.');let data;try{data=await response.json();}catch{throw new Error('No completed response was returned. Refresh before repeating a change.');}if(current!==epoch)throw new Error('Your session ended. Sign in again to continue.');if(!response.ok||data.ok===false||(data.result&&!['ok','verification_sent','request_received'].includes(data.result))){if(response.status===401){clearSession('Your private session ended. Sign in again.');throw new Error('Your private session ended. Sign in again.');}const code=String(data.result||data.code||'').toLowerCase();const err=new Error(errors[code]||(response.status===429?'Too many requests. Wait a moment before trying again.':response.status===503?errors.paused:response.status===410?'This private link has expired. Request access again or open the latest link you received.':response.status===403?errors.forbidden:response.status===409?errors.conflict:'The service did not accept the action. Your draft has not been cleared.'));err.code=code;throw err;}return data;}
 async function authRequest(path,body){const response=await fetch(config.supabase_url+'/auth/v1/'+path,{method:'POST',credentials:'omit',signal:AbortSignal.timeout(20000),headers:{apikey:config.publishable_key,'Content-Type':'application/json'},body:JSON.stringify(body)});let data;try{data=await response.json();}catch{throw new Error('The account service did not return a completed response.');}if(!response.ok)throw new Error(response.status===429?'Please wait before trying the account action again.':'The account action was not accepted. Check your credentials and confirmation email.');return data;}
