 function updateMembershipEntry(){const optional=state.is_operator&&!state.profile;if(state.profile)operatorJoinOpen=false;get('member-join-panel').hidden=Boolean(state.profile)||(optional&&!operatorJoinOpen);get('member-optional-join').hidden=!optional;get('member-show-join').setAttribute('aria-expanded',String(optional&&operatorJoinOpen));get('member-hide-join').hidden=!optional;get('member-join-title').textContent=optional?'Join as a member':'Activate your membership';get('member-join-description').textContent=optional?'Your operator access is ready. You can optionally accept an invitation to create your own member profile.':'Your account is verified and signed in. Membership begins when you accept a pilot invitation.';}
