 function acceptResult(data){if(!['none','accepted','failed','pending','unknown'].includes(data.delivery_state)||!Number.isFinite(Date.parse(data.expires_at)))throw new Error('The email service could not verify this invitation and its expiry.');deliveryState=data.delivery_state;expires.textContent='This invitation expires at '+new Date(data.expires_at).toISOString()+' (UTC).';update();}
 async function preparePreview(){if(busy||!token||!state?.is_operator||current!==epoch||!area.isConnected)return;setBusy(true);previewStatus.textContent='Checking the invitation, recipient and expiry. Nothing is being sent…';try{const data=await request('operator_invitation_status',{email,invite_token:inviteToken},ACCESS_ENDPOINT);if(current!==epoch||!area.isConnected)return;acceptResult(data);preview.hidden=false;previewButton.hidden=true;previewStatus.textContent='Invitation checked. Review the recipient and message before sending.';previewStatus.className='member-inline-status';}catch(error){if(current===epoch&&area.isConnected){preview.hidden=true;previewStatus.textContent='The invitation could not be verified. No email was sent. '+error.message;previewStatus.className='status error';}}finally{if(current===epoch)setBusy(false);}}
 async function handoff(isRetry){if(busy||!token||!state?.is_operator||current!==epoch||!area.isConnected||preview.hidden||!(isRetry?deliveryState==='failed':deliveryState==='none'))return;if(isRetry||!deliveryId)deliveryId=crypto.randomUUID();setBusy(true);feedback.textContent='Sending the invitation email once…';try{const data=await request('operator_invitation_send',{email,invite_token:inviteToken,delivery_id:deliveryId},ACCESS_ENDPOINT);if(current!==epoch||!area.isConnected)return;acceptResult(data);statusText(deliveryState==='accepted'?'Invitation email accepted by the provider. Recipient account setup is next.':messages[deliveryState],deliveryState!=='accepted');}catch(error){if(current!==epoch||!area.isConnected)return;deliveryState='unknown';update();feedback.textContent=messages.unknown+' '+error.message;statusText('The email send could not be confirmed. Check its status before trying another action.',true);}finally{if(current===epoch){setBusy(false);if(area.isConnected)update();}}}
