 function renderInvitation(result,recipient,preview=false){const box=get('operator-invite-result');if(!box)return;box.replaceChildren();if(!/^[a-f0-9]{64}$/.test(result.invite_token||'')){box.append(node('p','The invitation response did not include a usable private link. No link can be copied.','status error'));return;}const c=card(box,'Next: send this invitation',(!result.delivery_state||result.delivery_state==='none'?'The invitation has not been sent. ':'')+'Creating or approving an invitation does not send email. Preview the message below, then choose Send invitation email when available. You can also copy the link to share it yourself.');c.tabIndex=-1;c.setAttribute('role','region');c.setAttribute('aria-label','Invitation ready to share');if(recipient)c.append(node('p','Send only to: '+recipient,'member-note'));if(result.expires_at)meta(c,'Expires '+date(result.expires_at));if(result.invitation_id)meta(c,'Invitation reference: '+String(result.invitation_id).slice(0,8));const input=node('textarea');input.readOnly=true;input.value=MEMBER_URL+'#invite='+result.invite_token;input.setAttribute('aria-label','Private invitation link');c.append(input);button(c,'Copy invitation link',()=>copyLink(input,'Link copied. Now send it directly to '+(recipient||'the intended recipient')+', or choose Send invitation email below. Copying does not send it.'),true);invitationEmailPreview(c,result,recipient,preview);c.append(node('p','The private link is kept only in this page. Save it before refreshing or leaving if you may need to check the email status later. If the link is lost or expires, create a new invitation above for the same email, then preview and send it. Revoke an earlier unused invitation only if you can identify its reference.','small'));selectTab('operate');c.focus();}
