 function showEntry(mode,focus=true){if(!login)return;get('member-access-management').hidden=true;get('member-login-panel').hidden=false;get('member-access-request-panel').hidden=mode!=='request';get('member-create-panel').hidden=mode!=='invite';get('member-signin-panel').hidden=mode!=='signin'||Boolean(token);get('member-choice-signin').hidden=Boolean(token);get('member-choice-request').setAttribute('aria-pressed',String(mode==='request'));get('member-choice-invite').setAttribute('aria-pressed',String(mode==='invite'));get('member-choice-signin').setAttribute('aria-current',mode==='signin'?'page':'false');for(const [choice,id]of [['request','member-choice-request'],['signin','member-choice-signin'],['invite','member-choice-invite']])get(id).className='button'+(mode===choice?'':' secondary');get('member-signin-description').textContent=invitationToken?'Your private invitation is loaded. Sign in with the invited email address, then accept the invitation to join.':'Use the email and password for an existing Kapukai account. Members and Workshop operators sign in here.';if(token)get('member-join-panel').hidden=true;statusText(mode==='request'?'Start with an access request. No account, password or invitation is needed.':mode==='signin'?'Sign in to an existing account. An access request alone does not create one.':invitationToken?'Your invitation is loaded. Create your account, or choose Sign in if you already have one.':'Open the private invitation link shared by the operator, or enter its invitation code below.');if(focus)get(mode==='request'?'member-access-request-panel':mode==='signin'?'member-signin-panel':'member-create-panel').focus();}
